    for i in range(m):
        for j in range(n):
            if i == 0 or s[j] != 'a' + i - 1:
                dp[i][j+1] = dp[i-1][j+1]
                continue
            if j:
                dp[i][j+1] = dp[i][j] + 1
                continue
            dp[i][j+1] = dp[i][j]

    for i in range(m):
        dp[i][n] = 1 if dp[i][n] else dp[i][n-1]

