                if i > 0 and arr2[(i-1)*n + j] == arr1[(i-1)*n + j]:
                    arr2[i*n + j], arr2[(i-1)*n + j] = arr2[(i-1)*n + j], arr2[i*n + j]
    return swaps

def get_desired_arrangement(arr1):
    n = len(arr1) // 2
    if n**2 != len(arr1):
        return -1
    count = 0
    for i in range(2):
        for j in range(n-1):
            if arr1[i*n + j] != arr1[i*n + j+1] or arr1[i*n + j] != arr1[i*n + n + j] or arr1[i*n + j] != arr1[i*n + n + j+1]:
                return -1
        count += 1
    for k in range(n-1):
