        j = k
        while i != n-1-k or j != n-k:
            if arr1[i*n + j] == 1 and arr1[i*n + (n-1) - j] == 1:
                return -1
            i += 1
            j -= 1
        if i == n-1-2*k or j == n-(k+1):
