def find_beaeveractor_position(rules, initial_position, initial_direction, time_passed):
    x, y = initial_position
    direction = initial_direction

    for rule in rules:
        x0, y0, x1, y1 = rule
        if direction == 'U' and time_passed > abs(x1 - x0):
            x, y = x1, y0
        elif direction == 'D' and time_passed > abs(x0 - x1):
            x, y = x0, y1
        elif direction == 'R' and time_passed > abs(y1 - y0):
            x, y = x0, y1
        elif direction == 'L' and time_passed > abs(y0 - y1):
            x, y = x1, y0

    return x, y

