import sys

def find_largest_leaf_rooms(graph, start):
    visited = {start}
    current_layer = [start]
    while current_layer:
        next_layer = []
        for node in current_layer:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_layer.append(neighbor)
        if len(next_layer) == 1:
            return next_layer[0]
        current_layer = next_layer
    return -1

def get_time_from_leaf_to_ground(graph, start, leaf_room):
    if len(graph[start]) == 1 and start != leaf_room:
        return 0
    visited = {start}
    queue = [(start, 0)]
    while queue:
        node, time = queue.pop(0)
        if node in visited:
            continue
        visited.add(node)
        if node == leaf_room:
            return time
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, time + graph[node][neighbor]))
    return -1

def solve_problem(graph, leaves, leaf_times):
    guests_left = [0] * len(leaves)
    max_difference = float('-inf')
    max_guests = 0
    for l in leaf_times:
        while leaves:
            first_leaf = leaves.pop(0)
            last_leaf = find_largest_leaf_rooms(graph, first_leaf)
            if last_leaf == -1:
                break
            guest_time = get_time_from_leaf_to_ground(graph, first_leaf, last_leaf)
            if guest_time == 0:
                break
            if guest_time - leaf_times[first_leaf] > max_difference:
                max_difference = guest_time - leaf_times[first_leaf]
                max_guests = 1
            elif guest_time - leaf_times[first_leaf] == max_difference:
                max_guests += 1
            guests_left[first_leaf] += max_guests
            if guests_left[first_leaf] > len(leaves):
                break
            guests_left[last_leaf] += 1
            if guests_left[last_leaf] > len(leaves):
                break
            leaves += [last_leaf]
        if len(leaves) == 0:
            break
    return max_difference

if __name__ == "__main__":
