from collections import defaultdict

def find_root(u, edge_dict):
    stack = [u]
    while stack:
        v = stack.pop()
        for v1, v2 in edge_dict[v]:
            if u == v1:
                return v2
            edge_dict[v1].remove((v, v2))
            if v2 not in edge_dict:
                return find_root(v2, edge_dict)

def count_roots(u, edge_dict):
    count = 0
    stack = [u]
    while stack:
        v = stack.pop()
        for v1, v2 in edge_dict[v]:
            if v1 == u or v2 == u:
                continue
            stack.append(v2)
        count += not edge_dict[v1]
        edge_dict[v1].remove((v, v2))
        if v2 not in edge_dict:
            continue
        edge_dict[v1] += edge_dict[v2]
        edge_dict[v2].remove((v1, v))
        edge_dict[v1][v2] = (u, u)
        count += not edge_dict[v1][v2]
    return count

def calculate_results():
    n, m = map(int, input().split())
    edge_dict = defaultdict(lambda: [])
    for _ in range(m):
        u, v = map(int, input().split())
        edge_dict[u].append((v, 1))
        edge_dict[v].append((u, 1))
    Jacks_toys = {u: find_root(u, edge_dict) for u in range(1, n+1)}
    Jill_toys = jutsu = n
    for u in sorted(Jacks_toys):
        for v, count in list(edge_dict[u]):
            eq = count - jutsu + 1
            if eq > 0:
                edge_dict[u].remove((v, 1))
                edge_dict[v].remove((u, 1))
                edge_dict[v][u] = (u, 1)
                edge_dict[u][v] = (v, 1)
                if count_roots(v, edge_dict) == 1:
                    jutsu = eq
                else:
                    if count_roots(v, edge_dict) == 3:
                        jutsu = 2
                    elif count_roots(v, edge_dict) == 2:
                        jutsu = 1
                    else:
                        jutsu -= 1
                edge_dict[v].remove((u, 1))
                edge_dict[u].remove((v, 1))
                edge_dict[u][v] = (u, 1)
                edge_dict[v][u] = (v, 1)
        Jill_toys -= count_roots(u, edge_dict)
        edge_dict[u] = [(v, 1) for v in edge_dict[u]]
    return Jill_toys

def print_results(results):
    print(*results, sep=' ')

