def road_repairing(n, dots):
    workers = defaultdict(list)
    for i in range(1, n):
        workers[dots[0]].append((i, 99999999))
        workers[dots[i-1]].append((i, 99999999))

    for worker in workers[dots[0]]:
        curr = worker[0]
        if curr in dots:
            dots[worker[0]], dots[curr-1].appendleft(worker)
            workers[dots[curr-1]] = [(worker[0], 99999999)] + workers[dots[curr-1]]
            workers[dots[curr+1] if curr+1 < len(dots) else None].append(worker)
        else:
            dots[curr-1].appendleft(worker)
            workers[dots[curr-1]] = [(worker[0], 99999999)] + workers[dots[curr-1]]

    remaining = 99999999
    for worker in workers[dots[0]]:
        path_exists, queue = find_path_starts(workers, worker[0])

        if not path_exists:
            return -1

        for worker_path in queue:
            remaining = min(remaining, worker[1] + [max(x[1] for x in workers[worker[0]])], key=lambda x: x[1])

    return remaining

