from math import ceil
from typing import List

def solve(n: int, graph: List[List[int]]) -> str:
    k = (3 + 4) * (n // 7)
    if n % 7 != 0:
        k += (n % 7)
    if k > n * n:
        return "-1"

    result = []
    for cycle_len in range(3, 5):
        k_cycle = ceil(n / cycle_len)
        total_edges = (cycle_len - 1) * k_cycle + k * (3 - cycle_len)
        if total_edges <= n * n:
            less_than = k_cycle * ((cycle_len - 1) * (cycle_len - 2) // 2 + k * ((cycle_len - 1) * (cycle_len - 2) // 2 - 1))
            if less_than <= n * n:
                num_points = (3 - cycle_len) * k_cycle
                tot = cycle_len
                for i in range(cycle_len):
                    continue_cycle = True
                    points_for_this_cycle = 0
                    res = []
                    hsh = []
                    i_low = i if i else 0
                    for j in range(total_edges + i_low):
                        res.append([])
                        if j % num_points == 1 and not continue_cycle:
                            break
                        else:
                            continue_cycle = False
                        if total_edges + i_low > cycle_len and j % tot == 0:
                            continue_cycle = True
                            points_for_this_cycle -= 1
                            res[-1].append(j - 1)
                            hsh.append(["%d,%d" % (res[-3][0], j)])
                    if points_for_this_cycle > 0 and continue_cycle and j >= 0:
                        points_last = k_cycle
                        for start_index in range(j + 1, j + points_last):
                            if start_index % tot == 0:
                                if start_index not in hsh and hsh == []:
                                    continue
                                elif len(result) > 6:
                                    continue
                                else:
                                    result.append(7)
                                    continue_cycle = False 
                            res[-1].append(start_index)
                            hsh.append(["%d,%d" % (res[-3][0], start_index)])
                    if all([node not in hsh[i] for i, _ in enumerate(hsh)]):
                        return "\n".join([f"{cycle_len}{j in res}" for j in range(total_edges + i_low)])
    return "-1"


