import sys

def max_ducks_shot(knights, seconds):
    # Initialize variables
    dp = [0] * (seconds + 1)
    x_coordinates = [0] * (seconds * 2 + 1)
    for i in range(knights):
        hi, ti = map(int, input().split())
        x_coordinates[i * 2 + 1] = -hi
        x_coordinates[i * 2 + 2] = -ti
    x_coordinates = [x - seconds * 2 - 1 for x in x_coordinates]

    for knight in range(knights):
        for time in range(seconds, -1, -1):
            for left in range(knight * 2):
                hv = x_coordinates[left] + knight * 2
                if hv >= time:
                    dp[time] = max(dp[time], dp[time - (time - hv)])
            dp[time] += 1
    return max(dp)

