import sys

def max_ducks(n, r, origins):
    origins.sort()
    result = 0
    start_time = sys.maxsize

    for origin in origins:
        if origin <= start_time:
            result += 1
        else:
            start_time = origin + r

    # Check the last shot scenario
    if n - 1 > n - 17 * r:
        start_time = sys.maxsize
        result = 0
    else:
        if n - 1 <= n - 17 * r:
            result += 1
            origin = origins[n - 1]
            if origin <= start_time:
                result += 1
        else:
            if n - 1 >= 17 * r:
                for origin in origins:
                    if origin <= start_time:
                        result += 1
            else:
                for origin in reversed(range(2 * r, origins[-1] + r + 1, r)):
                    result += 1
    return result

