from collections import defaultdict

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = [(0, start)]
    visited = set()

    while queue:
        current_dist, current_node = heappop(queue)

        if current_dist > distances[current_node]:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node].items():
            distance = current_dist + weight
            if neighbor not in distances or distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(queue, (distance, neighbor))

    return distances

def get_lead_exit_nodes(graph, distances):
    lead_exit_nodes = set()

    for node, distances_of_neighbors in distances.items():
        for neighbor, distance in distances_of_neighbors.items():
            if distance == min(distances_of_neighbors.values()) and neighbor != node and ((distances[node] + distances_of_neighbors[neighbor] + 1) % 2 == 0):
                lead_exit_nodes.add(node)
                lead_exit_nodes.add(neighbor)

    return lead_exit_nodes

def is_connected(lead_exit_nodes):
    n = len(lead_exit_nodes)
    visited = set([lead_exit_nodes[0]])
    parent_map = {lead_exit_nodes[0]: None}

    for i in range(1, n):
        if lead_exit_nodes[i] in visited:
            parent = lead_exit_nodes[i]
        else:
            current_parent = parent_map[lead_exit_nodes[i-1]]
            while current_parent not in visited:
                parent = current_parent
                current_parent = parent_map[current_parent]
            parent = current_parent

        if parent == lead_exit_nodes[i]:
            return True
        else:
            visited.add(parent)
            parent_map[parent] = lead_exit_nodes[i]

    return False

