def lcs_length(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]


def count_strings_with_lcs(s, m):
    n = len(s)
    lcs_length = lcs_length(s, s)
    count = 0

    for i in range(m - 1, len(s)):
        if n - lcs_length == i - m:
