from collections import defaultdict

# Helper function to find all simple cycles in the graph
def find_cycles(graph):
    def dfs(v, parent, depth):
        if seen[v] == 1:
            if depth + 1 >= seen[pre[v]]:
                cycle = v
                while cycle != pre[pre[cycle]]:
                    cycle = pre[cycle]
                    seen[cycle] = depth + 1
                return True
        seen[v] = depth
        for neighbor in graph[v]:
            if neighbor != parent:
                stack = [neighbor]
                while stack:
                    node = stack.pop()
                    if node != pre[node]:
                        seen[pre[node]] = depth + 1
                        stack.append(pre[node])
                        stack.append(node)
                        pre[node] = len(stack)
                    else:
                        seen[pre[node]] = depth + 1
                        return False
        return False
    seen = defaultdict(int)
    pre = {}
    counter = 0
    for v in graph:
        if seen[v] == 0:
            counter += 1
            stack = [v]
            pre[v] = 0
            seen[v] = 0
            flags = [False] * len(stack)
            while stack:
                node = stack.pop()
                if not (flags[pre[node]] or (flags[counter - 1] and (depth[node] + 1) > seen[counter - 1])):
                    if dfs(node, node, depth[node]):
                        flags[counter - 1] = True
                        break
                    flags[counter - 1] = False
                    counter -= 1
    return counter

# Helper function to find the maximum number of Jill's toys
def max_jills_toys(n, edges):
    graph = defaultdict(list)
    visited = [False] * (n + 1)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)
    max_toys = [0] * (n + 1)
    for a in range(1, n + 1):
        if visited[a]:
            continue
        max_vertex = a
        pre = [max_vertex]
        depth = 0
        while max_vertex != -1:
            if visited[max_vertex]:
                break
            visited[max_vertex] = True
            seen = [-1] * (n + 1)
            pre.append(max_vertex)
            depth += 1
            max_toys[pre[-1]] += 1
            if not find_cycles(graph):
                break
            if not visited[a]:
                pre, max_vertex = -1, -1
                visited = [False] * (n + 1)
                continue
    max_jills = [0] * (n + 1)
    for vertex in range(n, 0, -1):
        max_jills[vertex] = max(max_jills[vertex + 1], max_toys[vertex])
    return max_jills

# Main function to solve the problem
def solve():
    n, m = map(int, input().split())
    edges = [list(map(int, input().split())) for _ in range(m)]
    for vertex in range(n + 1):
        visited = [False] * (n + 1)
        cycle = max_jills_toys(n, edges)
        while cycle[vertex] > -1:
            vertex = cycle[vertex]
        visited[vertex] = True
    return ' '.join(map(str, max_jills_toys(n, edges)))

