import bisect

def max_ducks(n, times):
    times.sort()
    buckets = [times[0]]
    for i in range(1, n):
        current_time = times[i]
        while len(buckets) > 1 and (buckets[-1] - current_time) / (current_time - buckets[0]) > 2:
            del buckets[-1]
        if current_time - buckets[-1] <= 1:
            buckets.append(current_time)
        else:
            idx = bisect.bisect(buckets, current_time)
            buckets[idx] = current_time
    return len(buckets)

