def max_jill_toys(n, m, edges):
    from collections import defaultdict

    # Build the cactus graph
    graph = defaultdict(set)
    for edge in edges:
        a, b = edge
        graph[a - 1].add(b - 1)
        graph[b - 1].add(a - 1)

    # Function to find the maximum number of Jill's toys on a cactus
    def max_toys(a):
        if not graph[a]:
            return 0
        incomplete_cycles = []
        for b in graph[a]:
            if a in incomplete_cycles or b in graph[a]:
                incomplete_cycles.append(b)

        # Directly mark these incomplete paths as empty
        for b in incomplete_cycles:
            graph[a].remove(b)
            graph[b].remove(a)

        no_toys = max(max_toys(a) for a in graph[a]) + 1
        for a in graph[a]:
            graph[a].add(a)
        graph[a] = []

        remaining_graph = graph.copy()
        remaining_graph[a].remove(b)
        remaining_lists = [sorted(c) for c in remaining_graph.values()]
        remaining = []

        for x, ys in remaining_lists:
            for y in ys:
                if (not y) in graph[y]:
                    for z in graph[y]:
                        remaining.append(z)

        for y in ys:
            for z in graph[y]:
                remaining.append(z)
        for z in remaining_lists:
            z.sort()
        return max(no_toys, max(max_toys(z) for z in remaining_lists))

    return [max_toys(a) for a in range(n)]

