from collections import defaultdict, Counter

def find_subsets_with_sum(s, target, min_val, nums, counts, memo):
    if target > nums[-1] * 2:
        return []

    if (target, min_val, []) in memo:
        return memo[target, min_val]

    subsets = []

    if min_val > nums[0]:
        subsets.append((nums[0], set()))  # Use the minimum value

    splits = set()

    for i in range(1, min(len(s), 100) + 1):
        for subset in find_subsets_with_sum(s[i:], target - s[:i], min(min_val, s[:i]), nums[i:], counts[i:], memo):
            if sum(subset) % 2 == 0:
                splits.add((subset, [s[:i], nums[:i]]))

    for subset in splits:
        for xi in subset[1]:
            counts[subset[0][0]].add(tuple(counts[subset[0][xi]]))
        subsets.append((subset[0], subset[1] | {len(subset[0])}))

    for subset in subsets:
        if sum(subset[0]) % 2 == 0:
            subsets.append((-subset[0], [len(subset[0])]))

    memo[target, min_val], memo[target, min_val + 1] = subsets
    return subsets

