def is_cactus(adj_list):
    visited = set()
    for i in range(1, len(adj_list)):
        for edge in adj_list[i]:
            if edge in visited:
                return False
        visited.add(i)
    return True

def find_max_jill_toys(n, edges):
    adj_list = [[] for _ in range(n + 1)]

    # Construct adjacency list from edges
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    cactus = [len(adj_list[i]) - 1 for i in range(1, n + 1)]

    # Check if the graph is a cactus
    if not is_cactus(cactus):
        cactus = [len(adj_list[i]) for i in range(1, n + 1)]

    max_toys = [0] * (n + 1)
    for a in range(n + 1):
        for _ in range(a, n + 1):
            subcactus = cactus[:]
            event = [0]
            for i in range(1, len(event)):
                cactus.remove(event[i])
                for j in adj_list[event[i - 1]]:
                    if j != event[i]:
                        cactus.append(j)
                i += 1

            if not is_cactus(cactus):
                cactus = subcactus
                break

        max_toys[a] = sum(cactus) - a
    return max_toys

